import { motion } from "framer-motion";
import { useEffect, useState } from "react";
import type { Wisdom } from "@/lib/types";
import { getSavedSlugs, toggleSave } from "@/lib/wisdom";

interface WisdomCardProps {
  wisdom: Wisdom;
  index?: number;
}

export function WisdomCard({ wisdom, index = 0 }: WisdomCardProps) {
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    setSaved(getSavedSlugs().includes(wisdom.slug));
  }, [wisdom.slug]);

  const handleSave = (e: React.MouseEvent) => {
    e.preventDefault();
    const isSaved = toggleSave(wisdom.slug);
    setSaved(isSaved);
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.preventDefault();
    const url = `${window.location.origin}/wisdom/${wisdom.slug}`;
    const text = wisdom.english_translation;
    if (navigator.share) {
      await navigator.share({ title: "Hikmah", text, url });
    } else {
      await navigator.clipboard.writeText(url);
    }
  };

  return (
    <motion.article
      initial={{ opacity: 0, y: 16 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-40px" }}
      transition={{ duration: 0.5, delay: index * 0.08 }}
      className="group relative"
    >
      <Link
        href={`/wisdom/${wisdom.slug}`}
        className="block rounded-2xl border border-border/80 bg-surface p-6 transition-all duration-300 hover:border-gold/30 hover:bg-surface-elevated md:p-8"
      >
        <p
          className="font-arabic text-center text-2xl leading-loose text-foreground md:text-3xl"
          dir="rtl"
          lang="ar"
        >
          {wisdom.arabic_text}
        </p>

        <div className="my-6 h-px bg-gradient-to-r from-transparent via-gold/20 to-transparent" />

        <p className="font-urdu text-center text-base leading-relaxed text-foreground/90" dir="rtl">
          {wisdom.urdu_translation}
        </p>

        <p className="mt-5 text-center text-sm leading-relaxed text-muted md:text-base">
          {wisdom.english_translation}
        </p>

        <div className="mt-6 flex items-center justify-between text-xs uppercase tracking-wider">
          <span className="text-gold-light">{wisdom.category?.name ?? "Wisdom"}</span>
          <span className="text-muted">{wisdom.source}</span>
        </div>

        {wisdom.short_reflection && (
          <p className="mt-4 line-clamp-2 text-sm italic text-foreground/60">
            {wisdom.short_reflection}
          </p>
        )}

        <div className="mt-6 flex items-center justify-between">
          <span className="text-sm text-gold transition-colors group-hover:text-gold-light">
            Read Reflection →
          </span>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={handleSave}
              className={`rounded-full p-2 transition-colors ${
                saved ? "text-gold" : "text-muted hover:text-foreground"
              }`}
              aria-label={saved ? "Unsave" : "Save"}
            >
              <Bookmark size={18} fill={saved ? "currentColor" : "none"} />
            </button>
            <button
              type="button"
              onClick={handleShare}
              className="rounded-full p-2 text-muted transition-colors hover:text-foreground"
              aria-label="Share"
