"use client";

import { useCallback, useEffect, useState } from "react";
import { motion } from "framer-motion";
import { Pause, Play, RotateCcw } from "lucide-react";

const FOCUS_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;

const focusQuotes = [
  "Your days are numbered — spend them on what builds you.",
  "The strong one controls himself when anger rises.",
  "Seeking knowledge is an obligation — start small, start now.",
  "You are but a collection of days. Make this one count.",
];

export function PomodoroTimer() {
  const [seconds, setSeconds] = useState(FOCUS_SECONDS);
  const [running, setRunning] = useState(false);
  const [onBreak, setOnBreak] = useState(false);
  const [quoteIndex, setQuoteIndex] = useState(0);

  const total = onBreak ? BREAK_SECONDS : FOCUS_SECONDS;
  const progress = ((total - seconds) / total) * 100;

  const tick = useCallback(() => {
    setSeconds((s) => {
      if (s <= 1) {
        setRunning(false);
        setOnBreak((b) => !b);
        return onBreak ? FOCUS_SECONDS : BREAK_SECONDS;
      }
      return s - 1;
    });
  }, [onBreak]);

  useEffect(() => {
    if (!running) return;
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [running, tick]);

  useEffect(() => {
    const id = setInterval(() => {
      setQuoteIndex((i) => (i + 1) % focusQuotes.length);
    }, 12000);
    return () => clearInterval(id);
  }, []);

  const reset = () => {
    setRunning(false);
    setOnBreak(false);
    setSeconds(FOCUS_SECONDS);
  };

  const mins = Math.floor(seconds / 60)
    .toString()
    .padStart(2, "0");
  const secs = (seconds % 60).toString().padStart(2, "0");

  return (
    <div className="flex flex-col items-center">
      <div className="relative flex h-64 w-64 items-center justify-center">
        <svg className="absolute inset-0 -rotate-90" viewBox="0 0 100 100">
          <circle cx="50" cy="50" r="45" fill="none" stroke="#1a1a1a" strokeWidth="2" />
          <circle
            cx="50"
            cy="50"
            r="45"
            fill="none"
            stroke="#c9a227"
            strokeWidth="2"
            strokeDasharray={`${progress * 2.83} 283`}
            strokeLinecap="round"
            className="transition-all duration-1000"
          />
        </svg>
        <span className="text-5xl font-light tabular-nums tracking-tight text-foreground">
          {mins}:{secs}
        </span>
      </div>

      <p className="mt-2 text-xs uppercase tracking-wider text-gold-muted">
        {onBreak ? "Break" : "Focus"}
      </p>

      <motion.p
        key={quoteIndex}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className="mt-10 max-w-md text-center text-sm italic text-muted"
      >
        {focusQuotes[quoteIndex]}
      </motion.p>

      <div className="mt-10 flex gap-4">
        <button
          type="button"
          onClick={() => setRunning(!running)}
          className="flex h-14 w-14 items-center justify-center rounded-full bg-gold/15 text-gold-light transition-colors hover:bg-gold/25"
          aria-label={running ? "Pause" : "Start"}
        >
          {running ? <Pause size={22} /> : <Play size={22} className="ml-0.5" />}
        </button>
        <button
          type="button"
          onClick={reset}
          className="flex h-14 w-14 items-center justify-center rounded-full border border-border text-muted transition-colors hover:text-foreground"
          aria-label="Reset"
        >
          <RotateCcw size={20} />
        </button>
      </div>
    </div>
  );
}

