"use client";

import { useState } from "react";
import { beforeYouTextPrompts } from "@/data/mock";
import { motion, AnimatePresence } from "framer-motion";

export default function BeforeYouTextPage() {
  const [step, setStep] = useState(0);
  const [done, setDone] = useState(false);
  const prompts = beforeYouTextPrompts;
  const current = prompts[step];

  const next = () => {
    if (step < prompts.length - 1) setStep(step + 1);
    else setDone(true);
  };

  return (
    <section className="mx-auto flex min-h-[calc(100vh-8rem)] max-w-lg flex-col justify-center px-4 py-12">
      <h1 className="text-center text-2xl font-medium text-foreground md:text-3xl">
        Before You Text Them
      </h1>
      <p className="mt-4 text-center text-sm text-muted">
        Five honest questions. No judgment — just clarity.
      </p>

      <AnimatePresence mode="wait">
        {done ? (
          <motion.section
            key="done"
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            className="mt-12 text-center"
          >
            <p className="text-lg text-gold-light">Breathe. Make wudu if you can. Then decide.</p>
            <button
              type="button"
              onClick={() => {
                setStep(0);
                setDone(false);
              }}
              className="mt-8 text-sm text-muted hover:text-foreground"
            >
              Start again
            </button>
          </motion.section>
        ) : (
          <motion.section
            key={current.id}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="mt-12 rounded-2xl border border-gold/20 bg-surface p-8"
          >
            <span className="text-xs uppercase tracking-wider text-gold-muted">
              {step + 1} of {prompts.length}
            </span>
            <p className="mt-6 text-xl leading-relaxed text-foreground">{current.question}</p>
            <button
              type="button"
              onClick={next}
              className="mt-8 w-full rounded-full bg-gold/15 py-3 text-sm font-medium text-gold-light hover:bg-gold/25"
            >
              {step < prompts.length - 1 ? "Next question" : "I have reflected"}
            </button>
          </motion.section>
        )}
      </AnimatePresence>
    </section>
  );
}

"use client";

import { useState } from "react";
import { categories } from "@/data/mock";

const initialForm = {
  arabic_text: "",
  urdu_translation: "",
  english_translation: "",
  category_id: categories[0]?.id ?? "",
  source: "",
  short_reflection: "",
  deep_reflection: "",
  action_steps: "",
  tags: "",
};

export default function AdminPage() {
  const [form, setForm] = useState(initialForm);
  const [status, setStatus] = useState<string | null>(null);

  const update = (key: keyof typeof form, value: string) => {
    setForm((f) => ({ ...f, [key]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus("Saving…");

    try {
      const res = await fetch("/api/wisdom", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...form,
          action_steps: form.action_steps.split("\n").filter(Boolean),
          tags: form.tags.split(",").map((t) => t.trim()).filter(Boolean),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed");
      setStatus("Saved. Card and reflection page will generate from this content.");
      setForm(initialForm);
    } catch (err) {
      setStatus(
        err instanceof Error
          ? err.message
          : "Connect Supabase to persist. Mock mode logs to console."
      );
      console.log("Wisdom draft:", form);
    }
  };

  return (
    <section className="mx-auto max-w-2xl px-4 py-12 md:px-6 md:py-16">
      <h1 className="text-2xl font-medium text-foreground">Wisdom CMS</h1>
      <p className="mt-2 text-sm text-muted">
        Add content once — cards, reflection pages, and topic links generate automatically.
      </p>

      <form onSubmit={handleSubmit} className="mt-10 space-y-4">
        {(
          [
            ["arabic_text", "Arabic text", "textarea"],
            ["urdu_translation", "Urdu translation", "textarea"],
            ["english_translation", "English translation", "textarea"],
            ["source", "Source", "input"],
            ["short_reflection", "Short reflection", "textarea"],
            ["deep_reflection", "Deep reflection", "textarea"],
            ["action_steps", "Action steps (one per line)", "textarea"],
            ["tags", "Tags (comma separated)", "input"],
          ] as const
        ).map(([key, label, type]) => (
          <label key={key} className="block">
            <span className="text-xs uppercase tracking-wider text-gold-muted">{label}</span>
            {type === "textarea" ? (
              <textarea
                value={form[key]}
                onChange={(e) => update(key, e.target.value)}
                required={key !== "action_steps" && key !== "tags"}
                rows={key === "deep_reflection" ? 6 : 3}
                className="mt-1 w-full rounded-xl border border-border bg-surface px-4 py-3 text-sm focus:border-gold/40 focus:outline-none"
              />
            ) : (
              <input
                type="text"
                value={form[key]}
                onChange={(e) => update(key, e.target.value)}
                className="mt-1 w-full rounded-xl border border-border bg-surface px-4 py-3 text-sm focus:border-gold/40 focus:outline-none"
              />
            )}
          </label>
        ))}

        <label className="block">
