export const SITE_NAME = "TheNahj";
export const SITE_TAGLINE = "Wisdom of Imam Ali (AS)";
export const SITE_DESCRIPTION =
  "A calm digital refuge helping modern youth navigate life through the wisdom of Imam Ali (AS).";

import { createHmac, timingSafeEqual } from "crypto";

const COOKIE_NAME = "thenahj-admin";
const MAX_AGE_MS = 24 * 60 * 60 * 1000;

export { COOKIE_NAME };

function getSecret(): string | null {
  return process.env.ADMIN_SECRET ?? process.env.ADMIN_PASSWORD ?? null;
}

export function createAdminToken(): string | null {
  const secret = getSecret();
  if (!secret) return null;

  const expires = Date.now() + MAX_AGE_MS;
  const payload = `${expires}`;
  const sig = createHmac("sha256", secret).update(payload).digest("hex");
  return `${payload}.${sig}`;
}

export function verifyAdminToken(token: string | undefined | null): boolean {
  if (!token) return false;
  const secret = getSecret();
  if (!secret) return false;

  const [expiresStr, sig] = token.split(".");
  if (!expiresStr || !sig) return false;

  const expires = Number(expiresStr);
  if (Number.isNaN(expires) || Date.now() > expires) return false;

  const expected = createHmac("sha256", secret).update(expiresStr).digest("hex");

  try {
    return timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
  } catch {
    return false;
  }
}

export function verifyAdminPassword(password: string): boolean {
  const expected = process.env.ADMIN_PASSWORD;
  if (!expected) return false;
  if (password.length !== expected.length) return false;
  try {
    return timingSafeEqual(Buffer.from(password), Buffer.from(expected));
  } catch {
    return false;
  }
}

export function isAdminAuthConfigured(): boolean {
  return Boolean(process.env.ADMIN_PASSWORD);
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { COOKIE_NAME, verifyAdminToken } from "@/lib/auth";

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const token = request.cookies.get(COOKIE_NAME)?.value;
  const isAuthed = verifyAdminToken(token);

  if (pathname.startsWith("/admin") && pathname !== "/admin/login") {
    if (!isAuthed) {
      const login = new URL("/admin/login", request.url);
      login.searchParams.set("next", pathname);
      return NextResponse.redirect(login);
    }
  }

  if (pathname === "/api/wisdom" && request.method === "POST" && !isAuthed) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  return NextResponse.next();
}

