import { NextResponse } from "next/server";
import { isSupabaseConfigured, supabase } from "@/lib/supabase";

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "")
    .slice(0, 80);
}

export async function POST(request: Request) {
  const body = await request.json();

  const slug = slugify(body.english_translation ?? body.arabic_text ?? "wisdom");

  const record = {
    slug,
    arabic_text: body.arabic_text,
    urdu_translation: body.urdu_translation,
    english_translation: body.english_translation,
    short_reflection: body.short_reflection,
    deep_reflection: body.deep_reflection,
    simple_meaning: body.simple_meaning || null,
    why_today: body.why_today || null,
    reflection_questions: body.reflection_questions ?? [],
    source: body.source,
    category_id: body.category_id,
    action_steps: body.action_steps ?? [],
    tags: body.tags ?? [],
    corner_topics: body.corner_topics ?? [],
    featured: Boolean(body.featured),
    trending: Boolean(body.trending),
  };

  if (!isSupabaseConfigured || !supabase) {
    return NextResponse.json(
      {
        error:
          "Supabase not configured. Add NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY to .env.local",
        draft: record,
      },
      { status: 503 }
    );
  }

  const { data, error } = await supabase.from("wisdom").insert(record).select().single();

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  return NextResponse.json({ success: true, data });
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { categories, studentTopics, youthTopics } from "@/data/mock";
import { SITE_NAME } from "@/lib/brand";

const topicOptions = [
  ...studentTopics.map((t) => ({ slug: t.slug, label: `Student: ${t.title}` })),
  ...youthTopics.map((t) => ({ slug: t.slug, label: `Youth: ${t.title}` })),
];

const initialForm = {
  arabic_text: "",
  urdu_translation: "",
  english_translation: "",
  category_id: categories[0]?.id ?? "",
  source: "",
  short_reflection: "",
  deep_reflection: "",
  simple_meaning: "",
  why_today: "",
  reflection_questions: "",
  action_steps: "",
  tags: "",
  corner_topics: [] as string[],
  featured: false,
  trending: false,
};

export default function AdminPage() {
  const router = useRouter();
  const [form, setForm] = useState(initialForm);
  const [status, setStatus] = useState<string | null>(null);

  const handleLogout = async () => {
    await fetch("/api/admin/logout", { method: "POST" });
    router.push("/admin/login");
    router.refresh();
  };

  const update = (key: keyof typeof form, value: string | boolean | string[]) => {
    setForm((f) => ({ ...f, [key]: value }));
  };

  const toggleTopic = (slug: string) => {
    setForm((f) => ({
      ...f,
      corner_topics: f.corner_topics.includes(slug)
        ? f.corner_topics.filter((s) => s !== slug)
        : [...f.corner_topics, slug],
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus("Saving…");

    try {
      const res = await fetch("/api/wisdom", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...form,
          action_steps: form.action_steps.split("\n").filter(Boolean),
          reflection_questions: form.reflection_questions.split("\n").filter(Boolean),
          tags: form.tags.split(",").map((t) => t.trim()).filter(Boolean),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Failed");
      setStatus(`Saved. Live at /wisdom/${data.data?.slug ?? "(check Supabase)"}`);
      setForm(initialForm);
    } catch (err) {
      setStatus(err instanceof Error ? err.message : "Save failed");
      console.log("Wisdom draft:", form);
    }
  };

  return (
    <section className="mx-auto max-w-2xl px-4 py-12 md:px-6 md:py-16">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-medium text-foreground">{SITE_NAME} CMS</h1>
          <p className="mt-2 text-sm text-muted">
            One form → wisdom card, reflection page, student/youth topic links, SEO.
          </p>
        </div>
        <button
          type="button"
          onClick={handleLogout}
          className="shrink-0 text-sm text-muted hover:text-foreground"
        >
          Sign out
        </button>
      </div>

      <form onSubmit={handleSubmit} className="mt-10 space-y-4">
        {(
          [
            ["arabic_text", "Arabic text", "textarea"],
            ["urdu_translation", "Urdu translation", "textarea"],
            ["english_translation", "English translation", "textarea"],
            ["source", "Source", "input"],
            ["short_reflection", "Short reflection", "textarea"],
            ["deep_reflection", "Deep reflection", "textarea"],
            ["simple_meaning", "Simple meaning", "textarea"],
            ["why_today", "Why this matters today", "textarea"],
            ["reflection_questions", "Reflection questions (one per line)", "textarea"],
            ["action_steps", "Action steps (one per line)", "textarea"],
            ["tags", "Tags (comma separated)", "input"],
          ] as const
        ).map(([key, label, type]) => (
          <label key={key} className="block">
            <span className="text-xs uppercase tracking-wider text-gold-muted">{label}</span>
            <textarea
              value={form[key]}
              onChange={(e) => update(key, e.target.value)}
              required={
                !["action_steps", "tags", "reflection_questions", "simple_meaning", "why_today"].includes(
                  key
                )
              }
              rows={key === "deep_reflection" ? 6 : 3}
              className="mt-1 w-full rounded-xl border border-border bg-surface px-4 py-3 text-sm focus:border-gold/40 focus:outline-none"
            />
          </label>
        ))}

        <label className="block">
          <span className="text-xs uppercase tracking-wider text-gold-muted">Category</span>
          <select
            value={form.category_id}
            onChange={(e) => update("category_id", e.target.value)}
            className="mt-1 w-full rounded-xl border border-border bg-surface px-4 py-3 text-sm"
          >
            {categories.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </label>

        <fieldset className="rounded-xl border border-border bg-surface p-4">
          <legend className="px-2 text-xs uppercase tracking-wider text-gold-muted">
            Corner topics (student / youth pages)
          </legend>
          <div className="mt-2 flex max-h-48 flex-wrap gap-2 overflow-y-auto">
            {topicOptions.map((t) => (
              <button
                key={t.slug}
                type="button"
                onClick={() => toggleTopic(t.slug)}
                className={`rounded-full px-3 py-1 text-xs transition-colors ${
                  form.corner_topics.includes(t.slug)
                    ? "bg-gold/20 text-gold-light"
                    : "bg-background text-muted hover:text-foreground"
                }`}
              >
                {t.label}
              </button>
            ))}
          </div>
        </fieldset>

        <motion-header className="flex gap-6">
          <label className="flex items-center gap-2 text-sm text-muted">
            <input
              type="checkbox"
              checked={form.featured}
              onChange={(e) => update("featured", e.target.checked)}
              className="rounded border-border"
            />
            Featured on home
          </label>
          <label className="flex items-center gap-2 text-sm text-muted">
            <input
              type="checkbox"
              checked={form.trending}
              onChange={(e) => update("trending", e.target.checked)}
              className="rounded border-border"
            />
            Trending
          </label>
        </motion-header>

        <button
          type="submit"
          className="w-full rounded-full bg-gold/15 py-3 text-sm font-medium text-gold-light hover:bg-gold/25"
        >
          Publish wisdom
        </button>
      </form>

      {status && <p className="mt-6 text-sm text-muted">{status}</p>}
    </section>
  );
}
